<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue';
import ReplayView from './ReplayView.vue';
import ScenePreview from './ScenePreview.vue';
import {loadApiReplay} from './apiReplay';
import {identity,selectedPackage,latestRequests,requestJSON} from './sceneClient';
const scenes=ref([]),selected=ref(''),detail=ref(null),loaded=ref(null),history=ref([]),replay=ref(null),status=ref(null),error=ref(''),busy=ref(false),mode=ref('no_pump');
const sourceError=ref('');
const selectedScene=computed(()=>scenes.value.find(x=>sceneKey(x)===selected.value));
const resources=computed(()=>loaded.value?.parameters.normal?.data.resources??loaded.value?.parameters.closure?.data.resources??null);
const gate=latestRequests();let disposed=false;
const sceneKey=s=>`${s.scenario_id}@${s.scenario_version}`;
const label=s=>s.scenario_id==='borden_reference_100k'?'Borden 参考场景':'多地形合成场景';
const endpoint=s=>`/api/v1/scene-catalog/${encodeURIComponent(s.scenario_id)}/versions/${s.scenario_version}`;
function clear(){detail.value=null;loaded.value=null;history.value=[];replay.value=null;status.value=null;error.value='';sourceError.value='';}
async function refreshHistory(s,tx){const value=await requestJSON(`/api/v1/runs?scenario_id=${encodeURIComponent(s.scenario_id)}&scenario_version=${s.scenario_version}`,{signal:tx.signal});for(const r of value.runs)identity(r,s);if(tx.current())history.value=value.runs;}
async function choose(){const tx=gate.begin();clear();busy.value=true;const s=scenes.value.find(x=>sceneKey(x)===selected.value);if(!s){busy.value=false;return;}
 try{await Promise.all([
  (async()=>{try{const value=selectedPackage(await requestJSON(endpoint(s),{signal:tx.signal}),s);if(tx.current()){detail.value=value;mode.value='no_pump';}}catch(e){if(tx.current())sourceError.value=e.message;}})(),
  (async()=>{try{await refreshHistory(s,tx);}catch(e){if(tx.current())error.value=e.message;}})()
 ]);}finally{if(tx.current())busy.value=false;}}
async function load(){const s=detail.value.scene,tx=gate.begin();busy.value=true;error.value='';replay.value=null;status.value=null;loaded.value=null;
 try{const value=selectedPackage(await requestJSON(endpoint(s)+'/load',{signal:tx.signal,body:{manifest_sha256:s.manifest_sha256}}),s);if(tx.current())loaded.value=value;}catch(e){if(tx.current())error.value=e.message;}finally{if(tx.current())busy.value=false;}}
async function viewRun(r){const s=selectedScene.value,tx=gate.begin();busy.value=true;replay.value=null;error.value='';status.value=r;
 try{identity(r,s);const value=await loadApiReplay(r.run_id,{signal:tx.signal,expectedScene:{scenario_id:s.scenario_id,scenario_version:s.scenario_version}});if(tx.current())replay.value=value;}catch(e){if(tx.current())error.value=e.message;}finally{if(tx.current())busy.value=false;}}
async function start(){const config=loaded.value,s=config.scene,selectedMode=mode.value,params=config.parameters[selectedMode];if(!params||!s.availability[selectedMode].allowed)return;
 const tx=gate.begin();busy.value=true;error.value='';replay.value=null;status.value=null;
 try{const health=await requestJSON('/api/v1/health',{signal:tx.signal});const runId=crypto.randomUUID(),key=crypto.randomUUID();const request={...JSON.parse(JSON.stringify(config.scenario)),kind:'run_request',run_id:runId,parameter_version:params.id,model_build:health.model_build,payload:{mode:selectedMode,idempotency_key:key}};
 let run=await requestJSON('/api/v1/runs',{signal:tx.signal,body:request,headers:{'Idempotency-Key':key}});identity(run,s);
 while(tx.current()){status.value=run;if(['succeeded','failed','cancelled'].includes(run.status))break;await new Promise(resolve=>setTimeout(resolve,700));if(!tx.current())return;run=await requestJSON('/api/v1/runs/'+runId,{signal:tx.signal});identity(run,s);}
 if(!tx.current())return;await refreshHistory(s,tx);
 if(run.status==='succeeded'){const value=await loadApiReplay(runId,{signal:tx.signal,expectedScene:s});if(tx.current())replay.value=value;}
 else if(tx.current())error.value=run.error?.message??run.status;
 }catch(e){if(tx.current())error.value=e.message;}finally{if(tx.current())busy.value=false;}}
onMounted(async()=>{const tx=gate.begin();busy.value=true;try{const c=await requestJSON('/api/v1/scene-catalog',{signal:tx.signal});if(c.catalog_version!=='dual-scenes-v1'||!Array.isArray(c.scenes))throw Error('Unknown scene catalog');if(!tx.current())return;scenes.value=c.scenes;selected.value=c.scenes.length?sceneKey(c.scenes[0]):'';await choose();}catch(e){if(tx.current()&&!disposed)error.value=e.message;}finally{if(tx.current()&&!disposed)busy.value=false;}});
onUnmounted(()=>{disposed=true;gate.cancel();});
</script>
<template><div class="scene-manager"><header class="scene-heading"><div><div class="eyebrow">BORDEN-100K / SCENARIO WORKSPACE</div><h1>道路 · 资源 · 地下水</h1><p>两套独立场景 · 输入、配置与运行结果按版本隔离</p></div><span class="badge">无需地图 API Key</span></header><section class="scene-controls panel"><label>选择场景 <select aria-label="选择场景" v-model="selected" @change="choose"><option v-for="s in scenes" :key="sceneKey(s)" :value="sceneKey(s)">{{label(s)}} · v{{s.scenario_version}}</option></select></label><span v-if="detail">seed {{detail.scene.seed}} · {{detail.scene.coordinate_frame}}</span><p role="status" v-if="busy">正在校验场景或执行真实计算…</p><p role="alert" v-if="error">{{error}}</p><p v-if="sourceError" aria-label="当前场景源包状态">{{sourceError}} · 当前源包不可用于新运行；已发布历史按其自身快照读取。</p><p v-if="!scenes.length&&!busy">目录未加载。不会自动回退到 fixture。</p></section><template v-if="detail"><section class="panel scene-config"><h2>{{label(detail.scene)}} · v{{detail.scene.scenario_version}}</h2><code>{{detail.scene.scenario_id}}</code><p>{{detail.scene.synthetic?'SYNTHETIC · 独立合成米制场景；所有设施与地形为程序生成。':'官方登记点地理参考 · 水文未现场配准；不是现场数字孪生。'}}</p><p>manifest SHA256：<code>{{detail.scene.manifest_sha256}}</code></p><div class="mode-gates"><p v-for="(g,m) in detail.scene.availability" :key="m">{{m}}：{{g.allowed?'允许显式运行':g.blockers.join(' · ')}}</p></div><button @click="load" :disabled="busy">加载场景配置</button><label>运行工况 <select aria-label="运行工况" v-model="mode"><option v-for="(g,m) in detail.scene.availability" :key="m" :value="m" :disabled="!g.allowed">{{m==='no_pump'?'无抽水 · 仅水文验证':m==='normal'?'正常道路':'封路绕行'}}</option></select></label><button class="primary" @click="start" :disabled="busy||!loaded?.parameters[mode]||!loaded?.scene.availability[mode].allowed">启动运行</button><p>显式历史评价窗口 day 0–21900；参考模型日 14600。控制期 signed 风险窗口限制仍保留，不自动改窗。</p><p v-if="status">run_id <code>{{status.run_id}}</code> · 状态 <strong>{{status.status}}</strong></p><div v-if="resources" class="resource-inputs" aria-label="场景资源配置"><p>车辆 {{resources.vehicles?.length??0}} · 人员组 {{resources.crews?.length??0}} · 设备 {{resources.equipment?.length??0}} · 任务 {{resources.tasks?.length??0}}</p><p v-for="item in resources.inventory??[]" :key="item.depot_id+item.item_id">{{item.depot_id}} / {{item.item_id}} · 库存 {{item.quantity}}</p></div><details v-if="loaded"><summary>当前配置快照（{{loaded.scenario.scenario_id}} v{{loaded.scenario.scenario_version}}）</summary><p>模式参数：{{Object.entries(loaded.parameters).map(([m,p])=>m+': '+(p?.id??'BLOCKED')).join(' / ')}}</p><pre>{{JSON.stringify({scenario:loaded.scenario.payload,parameters:loaded.parameters},null,2)}}</pre></details></section></template><ScenePreview v-if="replay?.sceneDisplay||detail?.display" :display="replay?.sceneDisplay??detail.display"/><section v-if="selectedScene" class="panel scene-history" aria-label="场景历史运行"><h2>此场景版本的历史运行</h2><p v-if="!history.length">暂无运行记录。</p><button v-for="r in history" :key="r.run_id" @click="viewRun(r)" :disabled="busy||r.status!=='succeeded'">{{r.run_id}} · {{r.status}} · {{r.parameter_version}}</button></section></div><ReplayView v-if="replay" :key="replay.scenario.run_id" :initial-data="replay"/></template>
